variable "entorno" {
  type        = string
  description = "Entorno de despliegue"
  default     = "dev"

  validation {
    condition     = contains(["dev", "pro"], var.entorno)
    error_message = "El entorno debe ser dev o pro."
  }
}

output "entorno_actual" {
  value = var.entorno
}
